const baseAiAnswer=aiAnswer;
aiAnswer=question=>{const q=question.toLowerCase();if(q.includes("práctica")||q.includes("practica")||q.includes("oportunidad")||q.includes("empleo")||q.includes("ayudant")||q.includes("investig")){const relevant=opportunities.filter(item=>!q.includes("informática")&&!q.includes("informatica")||item.career.includes("Informática")||item.career==="Todas las carreras");return `Oportunidades UBO disponibles:<br>${relevant.map(item=>`• ${item.title} · ${item.type} · cierre ${formatDate(item.deadline)}`).join("<br>")}`};return baseAiAnswer(question)};
const baseAiAnswerMarketplace=aiAnswer;
aiAnswer=question=>{const q=question.toLowerCase();if(q.includes("libro")||q.includes("apunte")||q.includes("marketplace")){const posts=marketplaceData().filter(item=>!q.includes("base de datos")||item.title.toLowerCase().includes("base de datos"));return posts.length?`Marketplace UBO tiene disponible:<br>${posts.map(item=>`• ${item.title} · ${item.type} · ${item.price}`).join("<br>")}`:"No encontré publicaciones disponibles para esa búsqueda."}return baseAiAnswerMarketplace(question)};
const baseAiAnswerTrajectory=aiAnswer;
aiAnswer=question=>{const q=question.toLowerCase();if(q.includes("cómo voy")||q.includes("como voy")||q.includes("qué debo mejorar")||q.includes("que debo mejorar")||q.includes("cuánto me falta")||q.includes("cuanto me falta")||q.includes("carrera")){const stats=trajectoryStats(),risk=courses.filter(item=>item.attendance<80).map(item=>item.name);return `Tu trayectoria muestra ${stats.percentage}% de avance curricular, promedio ${stats.average} y asistencia ${stats.attendance}%. ${risk.length?`Te conviene mejorar la asistencia en ${risk.join(", ")}. `:"Mantienes una asistencia favorable. "}Tienes ${stats.pending} ramos pendientes y ${studentGoals().filter(goal=>!goal.done).length} objetivos personales en progreso.`}return baseAiAnswerTrajectory(question)};
