function appendApiRecommendationResources(container){const requestId=`recommendations-${Date.now()}-${Math.random()}`;container.dataset.recommendationRequest=requestId;void getRecommendationsFromApi({fallback:[]}).then(result=>{if(!result.available||container.dataset.recommendationRequest!==requestId||!Array.isArray(result.recommendations)||!result.recommendations.length)return;const section=safeElement("div","student-recommendation-list api-recommendation-resources");section.append(safeElement("b","","Recursos LMS disponibles"));result.recommendations.slice(0,3).forEach(item=>{const row=safeElement("span","");row.append("📚 ",safeElement("strong","",item.title||"Recurso disponible"));if(item.resourceTitle)row.append(` · ${item.resourceTitle}`);section.append(row)});container.append(section)}).catch(()=>{})}
function renderStudentAcademicRecommendations(){const container=$("#student-academic-recommendations"),studentId=currentInstitutionalStudentId();if(!container)return;container.replaceChildren();if(!studentId){container.append(safeElement("p","card-meta","Inicia sesión para revisar tu plan académico demo."));return}const result=generateAcademicRecommendations(studentId,{persist:false});if(!result.available){container.append(safeElement("p","card-meta","No fue posible generar recomendaciones académicas demo."));return}const status=safeElement("article",`student-recommendation-status ${String(result.status||"").toLowerCase()}`),strengths=safeElement("div","student-recommendation-list"),weaknesses=safeElement("div","student-recommendation-list"),plan=safeElement("ol","student-study-plan");status.append(safeElement("span","student-recommendation-label",recommendationStatus(result.status)),safeElement("p","",result.recommendations[0]?.detail||"Revisa tu información académica demo."));strengths.append(safeElement("b","","Fortalezas"));(result.strengths.length?result.strengths:["Continúa construyendo hábitos de estudio."]).forEach(item=>strengths.append(safeElement("span","",item)));weaknesses.append(safeElement("b","","Mejorar"));(result.weaknesses.length?result.weaknesses:result.recommendations.map(item=>item.title)).slice(0,3).forEach(item=>weaknesses.append(safeElement("span","",item)));result.studyPlan.forEach(item=>{const row=safeElement("li","");row.append(safeElement("b","",`${item.day} · ${item.action}`),safeElement("span","",item.detail),safeElement("small","",item.resource));plan.append(row)});const resources=safeElement("div","student-recommendation-list");resources.append(safeElement("b","","Material recomendado"));(result.resources||[]).slice(0,3).forEach(item=>resources.append(safeElement("span","",`📚 ${item.title} · ${item.source}`)));container.append(status,strengths,weaknesses,safeElement("h4","","Plan de estudio"),plan);if(resources.children.length>1)container.append(resources);appendApiRecommendationResources(container)}
function submitStudentTutor(form){const studentId=currentInstitutionalStudentId(),result=studentId?askAcademicTutor({studentId,question:form.elements.question.value}):{answered:false,errors:["No se encontró una sesión estudiantil."]};if(!result.answered){const feedback=form.querySelector(".student-tutor-feedback");feedback.textContent=(result.errors||["No fue posible consultar el tutor demo."]).join(" ");feedback.className="student-tutor-feedback error";return}form.reset();renderStudentAcademicTutor();toast("Respuesta del tutor académico disponible.")}
document.addEventListener("submit",event=>{if(event.target.id!=="student-tutor-form")return;event.preventDefault();submitStudentTutor(event.target)});
