function renderLmsRecommendationList(recommendations){const list=document.createElement("div");list.className="student-lms-recommendation-list";recommendations.forEach(item=>{const card=safeElement("article","student-lms-recommendation"),copy=document.createElement("div"),resource=item.resource||{};copy.append(safeElement("b","",item.type||"Recomendación LMS"),safeElement("p","",item.reason||"Revisa la actividad disponible en el LMS."));if(resource.title)copy.append(safeElement("small","",`Material recomendado: ${resource.title}`));card.append(copy,safeElement("span","badge request","LMS"));list.append(card)});return list}
async function hydrateStudentLmsRecommendations(){const container=$("#student-academic-recommendations");if(!container)return;const requestId=`lms-recommendations-${Date.now()}-${Math.random()}`;container.dataset.lmsRecommendationRequest=requestId;container.dataset.recommendationRequest=requestId;const result=await getIntelligentRecommendationsFromApi({fallback:[]});if(container.dataset.lmsRecommendationRequest!==requestId)return;const protectedFailure=result.source==="backend"&&[401,403].includes(result.status);if(protectedFailure){container.replaceChildren(safeElement("p","student-progress-note","No fue posible acceder a tus recomendaciones LMS con la sesión actual."));return}if(!result.available)return;const recommendations=Array.isArray(result.recommendations)?result.recommendations:[];if(!recommendations.length){container.replaceChildren(safeElement("p","student-progress-note","Datos LMS insuficientes para generar recomendaciones accionables."));return}const intro=safeElement("article","student-recommendation-status lms"),note=safeElement("p","","Acciones derivadas de tu actividad LMS. No constituyen una evaluación académica oficial UBO.");intro.append(safeElement("span","student-recommendation-label","Recomendaciones LMS"),note);container.replaceChildren(intro,renderLmsRecommendationList(recommendations))}
